    rubric: [
      'Maintains past stack (`T[]`), present state (`T`), and future stack (`T[]`)',
      'Implements `set(newVal)`: pushes current present to past, sets present, and clears future',
      'Implements `undo()`: pops from past, sets present, pushes old present to future',
      'Implements `redo()`: pops from future, sets present, pushes old present to past',
      'Exposes `canUndo` and `canRedo` boolean flags',
    ],
    sampleAnswer: '```tsx\nimport { useState, useCallback } from \'react\';\n\nexport function useUndoableState<T>(initialPresent: T) {\n  const [past, setPast] = useState<T[]>([]);\n  const [present, setPresent] = useState<T>(initialPresent);\n  const [future, setFuture] = useState<T[]>([]);\n\n  const canUndo = past.length > 0;\n  const canRedo = future.length > 0;\n\n  const undo = useCallback(() => {\n    if (!canUndo) return;\n    const previous = past[past.length - 1];\n    const newPast = past.slice(0, past.length - 1);\n    setPast(newPast);\n    setFuture([present, ...future]);\n    setPresent(previous);\n  }, [canUndo, past, present, future]);\n\n  const redo = useCallback(() => {\n    if (!canRedo) return;\n    const next = future[0];\n    const newFuture = future.slice(1);\n    setPast([...past, present]);\n    setPresent(next);\n    setFuture(newFuture);\n  }, [canRedo, past, present, future]);\n\n  const set = useCallback((newPresent: T) => {\n    setPast((prev) => [...prev, present]);\n    setPresent(newPresent);\n    setFuture([]);\n  }, [present]);\n\n  return { state: present, set, undo, redo, canUndo, canRedo };\n}\n```',
    tags: ['coding', 'custom-hooks', 'undo-redo', 'state-management'],
    followUps: ['How can you limit the maximum history stack size to prevent excessive memory usage?'],
